(function () {
  "use strict";

  // The hero animation is a welcome, not a spinner: it runs once and then holds
  // still so nothing on a page the user reads keeps moving. A GIF cannot be
  // stopped from script and it cannot be photographed either -- browsers hand
  // back its first frame, not the one on screen -- so holding it means swapping
  // in a still of the frame the animation reaches at the cutoff. That still is
  // generated by tools/freeze_frame.py; change HOLD_MS and the still stops
  // matching the animation until the script is re-run with the same --at.
  //
  // The GIF runs 3200 ms and is built to loop: the mark draws itself by
  // ~1560 ms, a sheen sweeps it until ~2200 ms, and from 2560 ms it fades out
  // to an empty frame so the loop can start over. The hold therefore has to
  // land in the gap between the sheen and the fade, or the hero ends up blank.
  //
  // 2400 ms sits on frame 56, which the animation gives a 200 ms delay where
  // every other frame gets 40 ms -- the beat the animator built in for the
  // logo to settle on. Note the fade leaves only ~160 ms of slack after it:
  // this is close to the latest the hold can go.
  var HOLD_MS = 2400;

  var image = document.getElementById("home-hero-animation");
  if (!image) {
    return;
  }

  var animatedSrc = image.getAttribute("src");
  var stillSrc = image.getAttribute("data-still-src");
  if (!stillSrc) {
    return;
  }

  var timer = null;

  // Fetched up front because the swap has to be instant: waiting on the network
  // at the cutoff would blank the hero at the moment it is meant to settle.
  var preload = new Image();
  preload.src = stillSrc;

  function hold() {
    image.src = stillSrc;
  }

  function arm() {
    window.clearTimeout(timer);
    // The GIF starts animating when it is decoded, not when this script runs,
    // so a load that is still in flight gets the countdown started for it.
    if (image.complete) {
      timer = window.setTimeout(hold, HOLD_MS);
    } else {
      image.addEventListener("load", arm, { once: true });
    }
  }

  arm();

  // A back/forward restore hands back the page exactly as it was left, held
  // frame included. Restoring the GIF gives that arrival the same run of
  // animation as a fresh load.
  window.addEventListener("pageshow", function (event) {
    if (!event.persisted) {
      return;
    }
    image.src = animatedSrc;
    arm();
  });
})();

(function () {
  "use strict";

  // A card a viewer cannot open is still on the page, and clicking it has to
  // say why rather than do nothing. The wording is rendered into the card by
  // the template, because what to do next depends on whether anybody is signed
  // in: a guest needs the login, a viewer needs an administrator.
  var card = document.querySelector(".life-data-card-locked");
  if (!card) {
    return;
  }

  card.addEventListener("click", function () {
    var message = card.getAttribute("data-locked-message");
    if (message && window.gremlinToast) {
      window.gremlinToast(message);
    }
  });
})();

(function () {
  "use strict";

  // Each workflow card has an animation it plays only while it is being pointed
  // at. The three GIFs run from 650 KB to 2 MB, so the template ships them
  // without a `src` and the first hover is what fills it in: loading the home
  // page costs nothing extra, and a visitor who never reaches for a card never
  // downloads any of them.
  //
  // Once set, `src` stays set -- the GIF is in the HTTP cache by then, so later
  // hovers are instant. Stopping it between hovers is the stylesheet's job: it
  // hides the image with `visibility` rather than opacity alone, which is what
  // lets the browser suspend the animation while nobody is looking at it.
  var media = document.querySelectorAll(".card-hover-media[data-hover-src]");

  Array.prototype.forEach.call(media, function (image) {
    var card = image.closest(".life-data-card");
    if (!card) {
      return;
    }

    function load() {
      var src = image.getAttribute("data-hover-src");
      // Whichever of the two events below arrives first does the work; the
      // other still fires once and has to find nothing left to do.
      if (!src) {
        return;
      }
      image.removeAttribute("data-hover-src");
      image.src = src;
    }

    // `pointerenter` rather than `mouseenter` so a pen or a finger landing on
    // the card counts the same as a cursor. Focus is the keyboard's equivalent:
    // the card reveals its extra copy on :focus-visible, and the animation is
    // written to come with it.
    card.addEventListener("pointerenter", load, { once: true });
    card.addEventListener("focus", load, { once: true });
  });
})();
